import time

# State persists for this input's entire video; it is not reset between frames.
next_track_id = 1
active = {}
started_at = time.perf_counter()
processed_frames = 0

def iou_xywh(a, b):
    ax, ay, aw, ah = a
    bx, by, bw, bh = b
    x1, y1 = max(ax, bx), max(ay, by)
    x2, y2 = min(ax + aw, bx + bw), min(ay + ah, by + bh)
    intersection = max(0, x2 - x1) * max(0, y2 - y1)
    union = max(0, aw) * max(0, ah) + max(0, bw) * max(0, bh) - intersection
    return intersection / union if union > 0 else 0.0

def process(decoded, source_meta):
    global next_track_id, processed_frames
    detections = decoded['detections']
    frame_index = source_meta['frame_index']
    candidates = []
    for track_id, track in active.items():
        if frame_index - track['last_seen'] <= 30:
            for det_index, det in enumerate(detections):
                overlap = iou_xywh(track['bbox_xywh'], det['bbox_xywh'])
                if overlap >= 0.3:
                    candidates.append((overlap, track_id, det_index))
    candidates.sort(key=lambda item: (-item[0], item[1], item[2]))
    used_tracks, used_detections = set(), set()
    assigned = {}
    for overlap, track_id, det_index in candidates:
        if track_id not in used_tracks and det_index not in used_detections:
            assigned[det_index] = track_id
            used_tracks.add(track_id)
            used_detections.add(det_index)
    observed = []
    for det_index, det in enumerate(detections):
        if det_index in assigned:
            track_id = assigned[det_index]
        else:
            track_id = next_track_id
            next_track_id += 1
        active[track_id] = {'bbox_xywh': det['bbox_xywh'], 'last_seen': frame_index}
        observed.append({'track_id': track_id, 'bbox_xywh': det['bbox_xywh'], 'confidence': det['confidence'], 'class_id': det['class_id'], 'label': det['label']})
    for track_id in list(active):
        if frame_index - active[track_id]['last_seen'] > 30:
            del active[track_id]
    processed_frames += 1
    elapsed = max(time.perf_counter() - started_at, 1e-9)
    return {'frame_index': frame_index, 'timestamp_s': source_meta['timestamp_s'], 'width': decoded['width'], 'height': decoded['height'], 'objects': observed, 'person_count': len(observed), 'pipeline_fps': processed_frames / elapsed, 'inference_latency_ms': decoded['inference_latency_ms'], 'model': decoded['model'], 'precision': decoded['precision'], 'model_input': decoded['model_input'], 'model_output': decoded['model_output']}
